import json

MAX_OPTS = 250  # Jev nhận tối đa ~254 lựa chọn mỗi câu hỏi
CHAP_MASS, MAX_CHAPS, MIN_P = 0.9, 3, 0.05
OTHER = "KHONG_PHU_HOP"


def main(chuong: dict, muc_luc: str) -> dict:
    """Ứng viên nhóm = mọi nhóm của 1–3 chương Jev chọn (lấy chương theo xác suất đến khi cộng dồn >= 90%)."""
    criteria = {}
    probs = sorted(((c, p) for c, p in chuong["chuong"]["probabilities"].items() if c != OTHER), key=lambda x: -x[1])
    chosen, acc = [], 0.0
    for c, p in probs:
        if p < MIN_P or len(chosen) >= MAX_CHAPS or acc >= CHAP_MASS:
            break
        chosen.append(c)
        acc += p
    heads = json.loads(muc_luc)["headings"]
    for c in chosen:
        for code, name in heads.get(c, []):
            if len(criteria) < MAX_OPTS:
                criteria.setdefault(code, name)

    criteria[OTHER] = "Không nhóm nào trong danh sách bao trùm hàng hóa này"
    q = {"nhom": {"type": "choice",
                  "instructions": "Chọn nhóm 4 số trong Biểu thuế XNK Việt Nam bao trùm đúng hàng hóa được mô tả, "
                                  "theo nội dung nhóm và chú giải (Quy tắc 1). Khi hàng có thể vào nhiều nhóm, nhóm mô "
                                  "tả cụ thể nhất được ưu tiên (Quy tắc 3a).",
                  "criteria": criteria}}
    return {"questions": json.dumps(q, ensure_ascii=False),
            "chuong": ", ".join(f"{c} ({p:.0%})" for c, p in probs[:len(chosen)]),
            "so_ung_vien": len(criteria) - 1}

def main(answers: dict) -> dict:
    probs = sorted(answers["nhom"]["probabilities"].items(), key=lambda x: -x[1])
    chosen, total = [], 0.0
    for code, p in probs:
        total += p  # tính cả KHONG_PHU_HOP vào tổng, nhưng không chọn nó
        if code != "KHONG_PHU_HOP" and p >= 0.02:
            chosen.append(code)
        if len(chosen) >= 5 or total >= 0.95:
            break
    if not chosen:  # Jev nghiêng hẳn về KHONG_PHU_HOP -> vẫn thử 2 nhóm đầu, bước 2 tự từ chối nếu sai
        chosen = [c for c, _ in probs if c != "KHONG_PHU_HOP"][:2]
    return {"nhom": chosen}

import json


def main(muc_luc: str) -> dict:
    """Mục lục (hs_tree/muc_luc.json) -> câu hỏi Jev chọn chương. Chạy song song với node truy xuất."""
    ml = json.loads(muc_luc)
    crit = {no: f"Chương {no}: {c['name']} (Phần {c['section']}: {c['section_name']})" for no, c in ml["chapters"].items()}
    # không thêm lựa chọn "không chương nào": hàng nào cũng thuộc một chương, lựa chọn đó chỉ tranh xác suất
    q = {"chuong": {"type": "choice",
                    "instructions": "Chọn chương của Biểu thuế XNK Việt Nam chứa hàng hóa được mô tả. Tên Phần, Chương "
                                    "chỉ để tra cứu (Quy tắc 1): xét theo bản chất hàng hóa (vật liệu, công dụng, chức "
                                    "năng; là bộ phận của máy hoặc xe nào) chứ không theo việc trùng chữ.",
                    "criteria": crit}}
    return {"questions": json.dumps(q, ensure_ascii=False)}

